const fn = new Function(code + "\nreturn { fetchJSON };");
const { fetchJSON } = fn();
const fake404 = async () => ({ ok: false, status: 404, json: async () => ({}) });
let msg;
try { await fetchJSON("/api/x", fake404); } catch (e) { msg = e.message; }
if (msg !== "HTTP 404") throw new Error('A 404 must throw Error with message "HTTP 404" — got: ' + msg);

const fn = new Function(code + "\nreturn { fetchJSON };");
const { fetchJSON } = fn();
let captured;
const fake = async (u, o) => { captured = o; return { ok: true, status: 201, json: async () => ({}) }; };
await fetchJSON("/api/tasks", fake, { method: "POST", body: { title: "x" } });
if (captured.method !== "POST") throw new Error("method must be forwarded.");
if (captured.body !== '{"title":"x"}') throw new Error("body must be JSON.stringify(value) — got: " + captured.body);
if (captured.headers["Content-Type"] !== "application/json") throw new Error("Content-Type: application/json is required when a body is sent.");
